create extension if not exists pgcrypto;
create type public.content_status as enum ('draft','published','archived');
create type public.gallery_kind as enum ('gallery','before_after');
create table public.admins(user_id uuid primary key references auth.users(id) on delete cascade,display_name text not null,created_at timestamptz default now());
create table public.providers(id uuid primary key default gen_random_uuid(),name text not null,credentials text,title text,slug text unique not null,biography text,philosophy text,image_path text,is_featured boolean default false,status public.content_status default 'draft',sort_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.service_categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null,description text,hero_image_path text,status public.content_status default 'draft',sort_order int default 0,seo_title text,seo_description text,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.services(id uuid primary key default gen_random_uuid(),category_id uuid references public.service_categories(id) on delete cascade,name text not null,slug text unique not null,short_description text,description text,benefits jsonb default '[]',price_label text,duration_minutes int,image_path text,faq jsonb default '[]',status public.content_status default 'draft',sort_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.testimonials(id uuid primary key default gen_random_uuid(),client_name text default 'ENIVÈ Client',quote text not null,rating int check(rating between 1 and 5),is_featured boolean default false,status public.content_status default 'draft',sort_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.gallery_items(id uuid primary key default gen_random_uuid(),kind public.gallery_kind default 'gallery',category text not null,title text,image_path text not null,after_image_path text,alt_text text not null,consent_confirmed boolean default false,is_featured boolean default false,status public.content_status default 'draft',sort_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.blog_categories(id uuid primary key default gen_random_uuid(),name text not null,slug text unique not null);create table public.blog_posts(id uuid primary key default gen_random_uuid(),category_id uuid references public.blog_categories(id),author_provider_id uuid references public.providers(id),title text not null,slug text unique not null,excerpt text,body text,featured_image_path text,seo_title text,seo_description text,status public.content_status default 'draft',published_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
create table public.promotions(id uuid primary key default gen_random_uuid(),title text not null,description text,image_path text,cta_label text,cta_url text,starts_at timestamptz,ends_at timestamptz,is_featured boolean default false,status public.content_status default 'draft',created_at timestamptz default now(),updated_at timestamptz default now());create table public.announcements(id uuid primary key default gen_random_uuid(),message text not null,link_label text,link_url text,starts_at timestamptz,ends_at timestamptz,status public.content_status default 'draft',created_at timestamptz default now(),updated_at timestamptz default now());
create table public.contact_submissions(id uuid primary key default gen_random_uuid(),name text not null,email text not null,phone text,message text not null,is_read boolean default false,created_at timestamptz default now());create table public.site_settings(key text primary key,value jsonb not null,updated_at timestamptz default now());create table public.social_links(id uuid primary key default gen_random_uuid(),platform text not null,url text not null,sort_order int default 0,is_active boolean default true);
create table public.page_content(id uuid primary key default gen_random_uuid(),slug text unique not null,title text not null,eyebrow text,intro text,body text,seo_title text,seo_description text,status public.content_status default 'draft',sort_order int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$select exists(select 1 from public.admins where user_id=auth.uid())$$;
alter table public.admins enable row level security;alter table public.providers enable row level security;alter table public.service_categories enable row level security;alter table public.services enable row level security;alter table public.testimonials enable row level security;alter table public.gallery_items enable row level security;alter table public.blog_categories enable row level security;alter table public.blog_posts enable row level security;alter table public.promotions enable row level security;alter table public.announcements enable row level security;alter table public.contact_submissions enable row level security;alter table public.site_settings enable row level security;alter table public.social_links enable row level security;
alter table public.page_content enable row level security;
create policy "admin reads self" on public.admins for select to authenticated using(user_id=auth.uid());
do $$declare t text;begin foreach t in array array['providers','service_categories','services','testimonials','gallery_items','blog_posts','promotions','announcements'] loop execute format('create policy "public reads published %1$s" on public.%1$I for select to anon,authenticated using(status=''published'')',t);execute format('create policy "admins manage %1$s" on public.%1$I for all to authenticated using(public.is_admin()) with check(public.is_admin())',t);end loop;end$$;
create policy "public reads categories" on public.blog_categories for select using(true);create policy "admins manage categories" on public.blog_categories for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public sends inquiries" on public.contact_submissions for insert to anon,authenticated with check(length(name) between 1 and 120 and length(email) between 3 and 254 and length(message) between 1 and 4000);create policy "admins read inquiries" on public.contact_submissions for select to authenticated using(public.is_admin());create policy "admins update inquiries" on public.contact_submissions for update to authenticated using(public.is_admin()) with check(public.is_admin());create policy "admins delete inquiries" on public.contact_submissions for delete to authenticated using(public.is_admin());create policy "public reads settings" on public.site_settings for select using(true);create policy "admins manage settings" on public.site_settings for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public reads socials" on public.social_links for select using(is_active);create policy "admins manage socials" on public.social_links for all to authenticated using(public.is_admin()) with check(public.is_admin());create policy "public reads published pages" on public.page_content for select to anon,authenticated using(status='published');create policy "admins manage pages" on public.page_content for all to authenticated using(public.is_admin()) with check(public.is_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('provider-images','provider-images',true,5242880,array['image/jpeg','image/png','image/webp']),('service-images','service-images',true,5242880,array['image/jpeg','image/png','image/webp']),('gallery-images','gallery-images',true,8388608,array['image/jpeg','image/png','image/webp']),('before-after-images','before-after-images',true,8388608,array['image/jpeg','image/png','image/webp']),('blog-images','blog-images',true,5242880,array['image/jpeg','image/png','image/webp']),('promotion-images','promotion-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict do nothing;create policy "public reads images" on storage.objects for select using(bucket_id in('provider-images','service-images','gallery-images','before-after-images','blog-images','promotion-images'));create policy "admins upload images" on storage.objects for insert to authenticated with check(public.is_admin());create policy "admins update images" on storage.objects for update to authenticated using(public.is_admin());create policy "admins delete images" on storage.objects for delete to authenticated using(public.is_admin());
